<?php
/** Slice 5 — the worker's POS passes (pos.md "Proof": the worker): pos_pulls (SFTP, Square, failures and backoff), email_intake, depletion_runs. */
require __DIR__ . '/lib.php';
$w = pos_world();
$admin = at(1, DOWNTOWN);
$dana = at(30, DOWNTOWN);
$bea = at(28, DOWNTOWN);
$since = last_activity_id();
$sftp = source_id('SMOKE SFTP');
$square = source_id('SMOKE Square');
$mail = source_id('SMOKE Nightly mail');
$toast = source_id('SMOKE Toast export');
$FX = state_dir() . '/fixture';
$later = static fn (int $min): string => (new DateTimeImmutable('+' . $min . ' minutes'))->format(DATE_ATOM);
$sq_log = static fn (): array => array_values(array_map(static fn ($l) => json_decode($l, true), array_filter(explode("\n", (string) @file_get_contents($GLOBALS['FX'] . '/square.log')))));
$pull = static fn (int $s): array => q('SELECT * FROM source_pulls WHERE source_id = :s ORDER BY id DESC LIMIT 1', ['s' => $s])[0] ?? [];
@unlink($FX . '/square.log');

echo "1. pos_pulls — the SFTP and Square sources are due\n";
$r = worker('pos_pulls');
$p = $r['ran']['pos_pulls'] ?? [];
ok(($p['pulled'] ?? 0) === 2 && ($p['failed'] ?? 1) === 0 && ($r['errors'] ?? [1]) === [], 'the pass pulls the two scheduled sources (the upload and email ones are never pulled)');
$ps = $pull($sftp);
ok(($ps['kind'] ?? '') === 'scheduled' && $ps['status'] === 'ok' && $ps['file_name'] === 'sales_20261007.csv' && $ps['started_by'] === null, "SFTP: a scheduled pull, ok, the newest unseen file from the fixture dir, no person");
ok(json_decode((string) one('SELECT settings FROM sources WHERE id = :s', ['s' => $sftp]), true)['seen_files'] === ['sales_20261007.csv'] && is_file(FIX . '/sftp/sales_20261007.csv'), 'seen_files kept; the folder untouched');
ok((int) one("SELECT count(*) FROM pos_sales WHERE source_id = :s AND business_date = '2026-10-07'", ['s' => $sftp]) === 2, 'its two checks imported on 2026-10-07');
$run7 = live_run('2026-10-07');
ok($run7 !== null && $run7['started_by'] === null && $run7['status'] === 'done' && near(run_qty((int) $run7['id'], $w['chicken']), -2 * SANDWICH_CHICKEN_G), "the day the pull brought ran with started_by NULL (the worker): two sandwiches' chicken");
$pq = $pull($square);
ok(($pq['kind'] ?? '') === 'scheduled' && in_array($pq['status'], ['ok', 'partial'], true) && (int) $pq['sales_new'] === 3 && (int) $pq['lines_seen'] === 5 && (int) $pq['plus_new'] === 1, 'Square: three orders over two pages, five lines, one new PLU (2002)');
$log = $sq_log();
ok(count($log) === 2 && $log[0]['cursor'] === null && $log[1]['cursor'] === 'SMOKE-CURSOR-2' && $log[0]['locations'] === ['L-SMOKE'] && $log[0]['window'] !== null, '/v2/orders/search twice: the cursor followed, the location and the closed_at window sent');
ok($log[0]['auth_tail'] === 'oken' && $log[0]['body_has_token'] === false && $log[0]['version'] !== '', 'the bearer in the header (…oken), never in the body; Square-Version sent');
$o1 = q("SELECT s.business_date::text AS bd, l.plu, l.qty, l.modifiers FROM pos_sales s JOIN pos_sale_lines l ON l.sale_id = s.id WHERE s.source_id = :s AND s.external_id = 'SQ-ORDER-1' ORDER BY l.plu", ['s' => $square]);
ok(count($o1) === 2 && $o1[0]['bd'] === '2026-10-08' && (float) $o1[0]['qty'] === 2.0 && json_decode($o1[0]['modifiers'], true)[0]['code'] === 'XCHK', "SQ-ORDER-1 normalized: 2026-10-08 local, 2 sandwiches with XCHK (the modifier's catalog id)");
ok((string) one("SELECT business_date::text FROM pos_sales WHERE source_id = :s AND external_id = 'SQ-ORDER-3'", ['s' => $square]) === '2026-10-08', 'SQ-ORDER-3 closed 00:40 UTC = 20:40 local belongs to 2026-10-08');
$run8 = live_run('2026-10-08');
ok($run8 !== null && $run8['started_by'] === null && $run8['status'] === 'partial' && (int) $run8['lines_unmapped'] === 1, "2026-10-08 run by the worker, partial (Square's 2002 unmapped)");
ok(count(activity('source.pull_start', $since)) === 2 && count(activity('source.pull_done', $since)) === 2, 'source.pull_start and pull_done logged for each');
$r = worker('pos_pulls');
ok(($r['ran']['pos_pulls']['pulled'] ?? 1) === 0, 'at once again: nothing due (each pulled within its 60 minutes)');
$r = worker('pos_pulls', ['RI_WORKER_NOW' => $later(61)]);
ok(($r['ran']['pos_pulls']['pulled'] ?? 0) === 2 && ($r['ran']['pos_pulls']['sales_new'] ?? 1) === 0 && ($r['ran']['pos_pulls']['runs'] ?? 1) === 0, 'an hour on: both pulled again — no new file, the same orders: nothing new, no run');

echo "2. Pull now, a refund\n";
ok(post_json($bea, '/sales/sources/pull.php', ['source' => (string) $square])['code'] === 403, 'Bea cannot pull (purchasing.draft)');
$r = post_json($dana, '/sales/sources/pull.php', ['source' => (string) $toast]);
ok($r['code'] === 422 && str_contains($r['json']['error']['message'] ?? '', 'fed by upload'), 'Pull now on an upload source → 422 "fed by upload — drop a file"');
touch($FX . '/square_refund');
$r = post_json($dana, '/sales/sources/pull.php', ['source' => (string) $square]);
ok($r['code'] === 200 && ($r['json']['sales_changed'] ?? 0) === 1 && ($r['json']['sales_new'] ?? 1) === 0 && count($r['json']['runs'] ?? []) === 1, "Dana's Pull now with SQ-ORDER-1's G&T returned: one check changed, its day re-run");
ok(q("SELECT l.voided FROM pos_sale_lines l JOIN pos_sales s ON s.id = l.sale_id WHERE s.source_id = :s AND s.external_id = 'SQ-ORDER-1' AND l.plu = '3001'", ['s' => $square])[0]['voided'] === true && (int) live_run('2026-10-08')['run_no'] === 2, 'the returned line voided; 2026-10-08 run 2');
ok(($pull($square)['kind'] ?? '') === 'manual' && (int) $pull($square)['started_by'] === 30, 'the pull is manual, Dana\'s');
@unlink($FX . '/square_refund');

echo "3. Failures and backoff\n";
post_json($admin, '/sales/sources/credential.php', ['source' => (string) $square, 'kind' => 'bearer', 'label' => 'SMOKE refused', 'secret' => 'sq-bad-token']);
ri_sql("UPDATE sources SET last_ok_at = now() - interval '2 hours' WHERE id = :s", ['s' => $square]);
$r = worker('pos_pulls');
$pq = $pull($square);
ok(($r['ran']['pos_pulls']['failed'] ?? 0) >= 1 && $pq['status'] === 'failed' && str_contains((string) $pq['error'], '401'), 'a refused token: the pull failed — "Square refused the token (HTTP 401)."');
$s = q('SELECT consecutive_failures, EXTRACT(epoch FROM backoff_until - now())::int AS wait FROM sources WHERE id = :s', ['s' => $square])[0];
ok((int) $s['consecutive_failures'] === 1 && $s['wait'] > 840 && $s['wait'] <= 900, 'consecutive_failures 1, backoff 15 minutes');
ok(activity('source.pull_fail', $since) !== [] && !str_contains(json_encode(activity('source.pull_fail', $since)), 'sq-bad-token'), 'source.pull_fail logged, never the token');
$r = worker('pos_pulls');
ok(($r['ran']['pos_pulls']['pulled'] ?? 1) === 0 && ($r['ran']['pos_pulls']['failed'] ?? 1) === 0 && (int) one('SELECT consecutive_failures FROM sources WHERE id = :s', ['s' => $square]) === 1, 'the next pass skips it (backing off)');
worker('pos_pulls', ['RI_WORKER_NOW' => $later(16)]);
ok((int) one('SELECT consecutive_failures FROM sources WHERE id = :s', ['s' => $square]) === 2 && (int) one("SELECT count(*) FROM notifications WHERE kind = 'pull_failed' AND record_type = 'source' AND record_id = :s", ['s' => $square]) === 0, 'after the backoff: the second failure, 30 minutes now, no notice yet');
worker('pos_pulls', ['RI_WORKER_NOW' => $later(31)]);
$n = q("SELECT member_id, title FROM notifications WHERE kind = 'pull_failed' AND record_type = 'source' AND record_id = :s", ['s' => $square]);
ok((int) one('SELECT consecutive_failures FROM sources WHERE id = :s', ['s' => $square]) === 3 && count($n) === 1 && (int) $n[0]['member_id'] === 27 && str_contains($n[0]['title'], '3 times'), 'the third failure in a row: pull_failed to Marco (the site\'s Manager) once');
worker('pos_pulls', ['RI_WORKER_NOW' => $later(46)]);
ok((int) one('SELECT consecutive_failures FROM sources WHERE id = :s', ['s' => $square]) === 4 && (int) one("SELECT count(*) FROM notifications WHERE kind = 'pull_failed' AND record_type = 'source' AND record_id = :s", ['s' => $square]) === 1, 'the fourth: still one notice today');
$card = page($admin, '/sales/sources/');
ok(has($card, 'id="source-card-' . $square . '-failures"') && preg_match('#id="source-card-' . $square . '-state">backing off#', $card['body']) === 1, "the source's card: backing off, its failures counted");
post_json($admin, '/sales/sources/credential.php', ['source' => (string) $square, 'kind' => 'bearer', 'label' => 'SMOKE Square production', 'secret' => 'sq-smoke-token']);
touch($FX . '/square_429');
$r = post_json($admin, '/sales/sources/pull.php', ['source' => (string) $square]);
$msg = strtolower($r['json']['error']['message'] ?? '');
ok($r['code'] === 422 && (str_contains($msg, '429') || str_contains($msg, 'rate')), 'Square says 429: the pull refused in words (' . ($r['json']['error']['message'] ?? '') . ')');
ok((int) one('SELECT EXTRACT(epoch FROM backoff_until - now())::int FROM sources WHERE id = :s', ['s' => $square]) >= 119, 'the backoff honours Retry-After (≥ 120 s)');
@unlink($FX . '/square_429');
$r = post_json($admin, '/sales/sources/pull.php', ['source' => (string) $square]);
ok($r['code'] === 200 && (int) one('SELECT consecutive_failures FROM sources WHERE id = :s', ['s' => $square]) === 0 && one('SELECT backoff_until FROM sources WHERE id = :s', ['s' => $square]) === null, 'the token rotated back: Pull now ok, the failures cleared');

echo "4. email_intake\n";
$att = static fn (string $f): array => ['filename' => basename($f), 'content_base64' => base64_encode((string) file_get_contents($f))];
file_put_contents(getenv('FAKE_MALUMAIL_STATE'), json_encode(['mailboxes' => ['pos-intake@smoke.invalid' => [
    '1' => ['headers' => ['from' => 'SMOKE POS <pos@smoke.invalid>', 'subject' => 'Nightly sales 2026-10-09'], 'attachments' => [$att(FIX . '/email/nightly_20261009.csv')], 'flags' => []],
    '2' => ['headers' => ['from' => 'A Stranger <stranger@else.invalid>', 'subject' => 'sales'], 'attachments' => [$att(FIX . '/generic.csv')], 'flags' => []],
    '3' => ['headers' => ['from' => 'pos@smoke.invalid', 'subject' => 'Nightly sales — no file'], 'attachments' => [], 'flags' => []],
]]]));
@unlink(getenv('FAKE_MALUMAIL_LOG') . '.mcp');
$r = worker('email_intake');
$e = $r['ran']['email_intake'] ?? [];
ok(($e['read'] ?? 0) === 3 && ($e['imported'] ?? 0) === 1 && ($e['unclaimed'] ?? 0) === 1 && ($e['failed'] ?? 0) === 1, 'three unread: one imported, one unclaimed, one with no file');
$pm = q("SELECT * FROM source_pulls WHERE source_id = :s AND kind = 'email' AND status = 'ok'", ['s' => $mail]);
ok(count($pm) === 1 && $pm[0]['file_name'] === 'nightly_20261009.csv' && $pm[0]['started_by'] === null && (int) $pm[0]['attachment_id'] > 0, 'an email pull for "SMOKE Nightly mail", ok, the file kept');
ok((int) one("SELECT count(*) FROM pos_sales WHERE source_id = :s AND business_date = '2026-10-09'", ['s' => $mail]) === 2 && live_run('2026-10-09') !== null && live_run('2026-10-09')['started_by'] === null, 'its two checks on 2026-10-09, the day run by the worker');
ok(str_contains((string) one("SELECT error FROM source_pulls WHERE source_id = :s AND status = 'failed' ORDER BY id DESC LIMIT 1", ['s' => $mail]), 'no CSV or XLSX'), 'the mail with no file: a failed pull saying so');
$st = json_decode((string) file_get_contents(getenv('FAKE_MALUMAIL_STATE')), true)['mailboxes']['pos-intake@smoke.invalid'];
ok(in_array('\\Seen', $st['1']['flags'], true) && in_array('\\Seen', $st['3']['flags'], true) && !in_array('\\Seen', $st['2']['flags'], true), "marked seen: the imported mail and the one with no file (handled); the stranger's left unread");
$calls = array_map(static fn ($l) => json_decode($l, true), array_filter(explode("\n", (string) file_get_contents(getenv('FAKE_MALUMAIL_LOG') . '.mcp'))));
$reads = array_values(array_filter($calls, static fn ($c) => $c['tool'] === 'read_message'));
ok(array_column(array_column($reads, 'args'), 'uid') === [1, 3] && ($reads[0]['args']['mark_seen'] ?? true) === false, "only the claimed mails read, never marking on read; the stranger's never opened");
$order = array_column($calls, 'tool');
ok(array_search('mark_message', $order, true) > array_search('read_message', $order, true), 'marked only after the read and the pull row');
$nt = q("SELECT member_id FROM notifications WHERE kind = 'pull_failed' AND title = 'A POS file from stranger@else.invalid matched no source'");
ok(count($nt) === 1 && (int) $nt[0]['member_id'] === 1, 'one notice to the admin naming the stranger');
$r = worker('email_intake');
ok(($r['ran']['email_intake']['read'] ?? 0) === 1 && ($r['ran']['email_intake']['unclaimed'] ?? 0) === 1 && (int) one("SELECT count(*) FROM notifications WHERE title = 'A POS file from stranger@else.invalid matched no source'") === 1, 'again: the stranger\'s still unread, still one notice today; nothing re-imported');

echo "5. depletion_runs\n";
ri_sql("UPDATE pos_sales SET imported_at = now() WHERE source_id = :s AND external_id = 'SFTP-101'", ['s' => $sftp]);
ok(is_due('2026-10-07') && is_due(D1, AIRPORT), 'two days due: Downtown 2026-10-07 (a check touched) and Airport day 1 (no storage area)');
$r = worker('depletion_runs');
$d = $r['ran']['depletion_runs'] ?? [];
ok(($d['ran'] ?? 0) === 1 && ($d['failed'] ?? 0) === 1, 'the pass: one ran, one failed');
$r7 = live_run('2026-10-07');
ok((int) $r7['run_no'] === 2 && $r7['started_by'] === null && !is_due('2026-10-07'), 'Downtown 2026-10-07: run 2 by the worker, no longer due');
$j = req('GET', '/sales/runs/' . $r7['id'], ['jar' => $dana, 'headers' => ['Accept: application/json']]);
ok((json_decode($j['body'], true)['data']['run']['by'] ?? '') === 'worker', 'its page says by "worker"');
$na = q("SELECT member_id FROM notifications WHERE kind = 'pull_failed' AND title = 'The depletion of 2026-10-05 could not run'");
ok(is_due(D1, AIRPORT) && count($na) === 1, "Airport's day left due; its Manager (the admin there) told once");
worker('depletion_runs');
ok((int) one("SELECT count(*) FROM notifications WHERE title = 'The depletion of 2026-10-05 could not run'") === 1, 'the next pass fails it again, no second notice today');
$wp = activity('worker.pass', $since);
ok($wp !== [] && !str_contains(json_encode($wp), 'sq-smoke-token') && !str_contains(json_encode($wp), 'sq-bad-token') && (int) one("SELECT count(*) FROM activity_log WHERE action = 'depletion.run' AND id > :s AND actor_member_id IS NULL", ['s' => $since]) >= 3, 'worker.pass logged with counts and no secret; the worker\'s runs have no actor');
finish();
